/*
 * Self-hosting bundles: a tiny store-only ZIP writer (no dependencies) and
 * helpers for producing a customised copy of the widget / web app.
 */

export const BUNDLES = {
  widget: {
    dir: "widget",
    zip: "qr-meeting-join-widget.zip",
    files: ["index.html", "lib.js", "widget.js", "widget.css"],
  },
  webapp: {
    dir: "webapp",
    zip: "qr-meeting-join-webapp.zip",
    files: [
      "index.html",
      "app.js",
      "lib.js",
      "oauth.js",
      "webex.js",
      "sdk.js",
      "scanner.js",
      "styles.css",
      "favicon.svg",
      "app-config.js",
      "config.js",
    ],
  },
};

let crcTable;
export function crc32(bytes) {
  if (!crcTable) {
    crcTable = new Uint32Array(256);
    for (let n = 0; n < 256; n += 1) {
      let c = n;
      for (let k = 0; k < 8; k += 1)
        c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      crcTable[n] = c >>> 0;
    }
  }
  let crc = 0xffffffff;
  for (const byte of bytes) crc = crcTable[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

/** @param {{name: string, data: Uint8Array}[]} files */
export function makeZip(files) {
  const enc = new TextEncoder();
  const chunks = [];
  const central = [];
  let offset = 0;

  for (const { name, data } of files) {
    const nameBytes = enc.encode(name);
    const crc = crc32(data);
    const local = new DataView(new ArrayBuffer(30));
    local.setUint32(0, 0x04034b50, true);
    local.setUint16(4, 20, true);
    local.setUint16(6, 0x0800, true); // UTF-8 names
    local.setUint32(14, crc, true);
    local.setUint32(18, data.length, true);
    local.setUint32(22, data.length, true);
    local.setUint16(26, nameBytes.length, true);
    chunks.push(new Uint8Array(local.buffer), nameBytes, data);

    const entry = new DataView(new ArrayBuffer(46));
    entry.setUint32(0, 0x02014b50, true);
    entry.setUint16(4, 20, true);
    entry.setUint16(6, 20, true);
    entry.setUint16(8, 0x0800, true);
    entry.setUint32(16, crc, true);
    entry.setUint32(20, data.length, true);
    entry.setUint32(24, data.length, true);
    entry.setUint16(28, nameBytes.length, true);
    entry.setUint32(42, offset, true);
    central.push(new Uint8Array(entry.buffer), nameBytes);

    offset += 30 + nameBytes.length + data.length;
  }

  const centralSize = central.reduce((n, c) => n + c.length, 0);
  const end = new DataView(new ArrayBuffer(22));
  end.setUint32(0, 0x06054b50, true);
  end.setUint16(8, files.length, true);
  end.setUint16(10, files.length, true);
  end.setUint32(12, centralSize, true);
  end.setUint32(16, offset, true);

  const all = [...chunks, ...central, new Uint8Array(end.buffer)];
  const out = new Uint8Array(all.reduce((n, c) => n + c.length, 0));
  let pos = 0;
  for (const chunk of all) {
    out.set(chunk, pos);
    pos += chunk.length;
  }
  return out;
}

/** Contents of webapp/config.js for a self-hosted copy. */
export function buildWebappConfigJs({
  clientId = "C2afd0fbf8197e1d5630a86e5979e958603b87d0e448ded5b426de2b1b91e6d3a",
  scopes = [
    "spark:kms spark:all meeting:schedules_read spark:people_read meeting:preferences_read",
  ],
  allowedEndpointHosts = [],
} = {}) {
  return `/* Generated by the configuration wizard. */
window.WEBAPP_CONFIG = ${JSON.stringify({ clientId, scopes, allowedEndpointHosts }, null, 2)};
`;
}
